import { build } from "esbuild";
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const local = (path) => new URL(path, import.meta.url);
const source = (path) => readFile(local(path), "utf8");
const hash = (text, format) => createHash("sha256").update(text).digest(format);
const result = await build({
  entryPoints: [fileURLToPath(local("./app.mjs"))],
  platform: "browser",
  format: "iife",
  target: "es2022",
  // Isolate generated bytes from any parent repository or user tsconfig.
  tsconfigRaw: { compilerOptions: { alwaysStrict: true } },
  bundle: true,
  minify: true,
  legalComments: "none",
  write: false,
  charset: "utf8",
  metafile: true,
});
if (
  Object.keys(result.metafile.outputs).length !== 1 ||
  Object.values(result.metafile.outputs)[0].imports.length
)
  throw new Error("Wallet must bundle all executable dependencies.");
let html = await source("./template.html");
const css = await source("./style.css");
const js = result.outputFiles[0].text;
if (/<\/script/i.test(js) || /<\/style/i.test(css))
  throw new Error("Unsafe inline asset delimiter.");
function replace(token, value) {
  if (html.split(token).length !== 2)
    throw new Error("Expected one template token: " + token);
  html = html.replace(token, () => value);
}
replace("__WALLET_SCRIPT__", js);
replace("__WALLET_STYLE__", css);
const scripts = [...html.matchAll(/<script>([\s\S]*?)<\/script>/gi)];
const styles = [...html.matchAll(/<style>([\s\S]*?)<\/style>/gi)];
if (scripts.length !== 1 || styles.length !== 1)
  throw new Error("Expected one inline script and stylesheet.");
const csp =
  "default-src 'none'; connect-src 'none'; script-src 'sha256-" +
  hash(scripts[0][1], "base64") +
  "'; style-src 'sha256-" +
  hash(styles[0][1], "base64") +
  "'; img-src data:; form-action 'none'; base-uri 'none'; object-src 'none'";
replace("__WALLET_CSP__", csp);
const licensePaths = {
  "@p2party/ledger-client": "LICENSE.md",
  "@noble/post-quantum": "LICENSE",
  "@noble/hashes": "LICENSE",
  "@noble/curves": "LICENSE",
  jose: "LICENSE.md",
  qr: "LICENSE",
};
const licenses = [];
for (const [name, file] of Object.entries(licensePaths))
  licenses.push(
    name + "\n" + (await source("../node_modules/" + name + "/" + file)),
  );
licenses.push(
  "qr (additional license)\n" +
    (await source("../node_modules/qr/LICENSE-MIT")),
);
if (licenses.some((s) => s.includes("-->")))
  throw new Error("Invalid license delimiter.");
html +=
  "\n<!-- Bundled dependency licenses\n" +
  licenses.map((license) => license.replace(/[ \t]+$/gm, "")).join("\n\n") +
  "\n-->\n";
await writeFile(local("./restore-wallet.html"), html);
const checksum = hash(html, "hex") + "  restore-wallet.html\n";
await writeFile(local("./restore-wallet.html.sha256"), checksum);
console.log(checksum.trim());
